// Press Run. This file is the startup file.
// Right-click another example and choose Run this file to run that one instead.
// Press Stop to end the animation.

use core {*}
use canvas

Ball :: struct {
    x, y, vx, vy, r: f32;
    color: str;
}

main :: () {
    canvas.init();
    w, h := canvas.get_size();

    colors := str.[ "#7aa2f7", "#e06c75", "#98c379", "#e5c07b", "#c678dd", "#56b6c2" ];

    balls: [6] Ball;
    for i in 0 .. 6 {
        speed := random.float(1.6f, 3.4f);
        vx := speed;
        if i % 2 == 0 do vx = -speed;

        balls[i] = .{
            random.float(60.0f, w - 60.0f),
            random.float(60.0f, h - 60.0f),
            vx,
            random.float(-3.0f, 3.0f),
            random.float(14.0f, 26.0f),
            colors[i],
        };
    }

    while true {
        canvas.fill_style("#18181b");
        canvas.fill_rect(0.0f, 0.0f, w, h);

        for i in 0 .. 6 {
            b := balls[i];
            b.x += b.vx;
            b.y += b.vy;

            if b.x < b.r || b.x > w - b.r do b.vx = -b.vx;
            if b.y < b.r || b.y > h - b.r do b.vy = -b.vy;

            canvas.fill_style(b.color);
            canvas.begin_path();
            canvas.arc(b.x, b.y, b.r, 0.0f, math.TAU);
            canvas.fill();

            balls[i] = b;
        }

        canvas.sync();
    }
}

// An analog clock. The time is UTC.
// Right-click this file and choose Run this file.

use core {*}
use canvas

draw_hand :: (angle, length, width: f32, color: str) {
    canvas.save();
    canvas.rotate(angle);
    canvas.stroke_style(color);
    canvas.line_width(width);
    canvas.line_join(canvas.LineJoin.Round);
    canvas.begin_path();
    canvas.move_to(-length * 0.12f, 0.0f);
    canvas.line_to(length, 0.0f);
    canvas.stroke();
    canvas.restore();
}

main :: () {
    canvas.init();
    w, h := canvas.get_size();
    radius := math.min(w, h) * 0.38f;

    while true {
        now := time.now();

        canvas.fill_style("#18181b");
        canvas.fill_rect(0.0f, 0.0f, w, h);

        canvas.save();
        canvas.translate(w / 2.0f, h / 2.0f);

        canvas.stroke_style("#3f4451");
        canvas.line_width(2.0f);
        for i in 0 .. 12 {
            canvas.save();
            canvas.rotate(cast(f32) i / 12.0f * math.TAU);
            canvas.begin_path();
            canvas.move_to(radius - 14.0f, 0.0f);
            canvas.line_to(radius, 0.0f);
            canvas.stroke();
            canvas.restore();
        }

        canvas.stroke_style("#9aa0a6");
        canvas.line_width(6.0f);
        canvas.begin_path();
        canvas.arc(0.0f, 0.0f, radius, 0.0f, math.TAU);
        canvas.stroke();

        hour := cast(f32) (now.hour % 12) + cast(f32) now.min / 60.0f;
        minute := cast(f32) now.min + cast(f32) now.sec / 60.0f;
        draw_hand((hour / 12.0f) * math.TAU - math.PI / 2.0f, radius * 0.50f, 6.0f, "#e5c07b");
        draw_hand((minute / 60.0f) * math.TAU - math.PI / 2.0f, radius * 0.72f, 4.0f, "#abb2bf");
        draw_hand((cast(f32) now.sec / 60.0f) * math.TAU - math.PI / 2.0f, radius * 0.80f, 2.0f, "#e06c75");

        canvas.fill_style("#7aa2f7");
        canvas.begin_path();
        canvas.arc(0.0f, 0.0f, 5.0f, 0.0f, math.TAU);
        canvas.fill();

        canvas.restore();
        canvas.sync();
    }
}

// Move the mouse over the canvas. The blue circle eases toward the cursor.
// Right-click this file and choose Run this file.

use core {*}
use canvas

main :: () {
    canvas.init();
    w, h := canvas.get_size();

    px := w / 2.0f;
    py := h / 2.0f;

    while true {
        mx, my := canvas.mouse_position();
        px += (mx - px) * 0.12f;
        py += (my - py) * 0.12f;

        canvas.fill_style("#18181b");
        canvas.fill_rect(0.0f, 0.0f, w, h);

        canvas.stroke_style("#3a3f4b");
        canvas.line_width(2.0f);
        canvas.begin_path();
        canvas.move_to(mx, my);
        canvas.line_to(px, py);
        canvas.stroke();

        canvas.fill_style("#7aa2f7");
        canvas.begin_path();
        canvas.arc(px, py, 16.0f, 0.0f, 6.283185f);
        canvas.fill();

        canvas.fill_style("#e5c07b");
        canvas.begin_path();
        canvas.arc(mx, my, 5.0f, 0.0f, 6.283185f);
        canvas.fill();

        canvas.sync();
    }
}

// Click and drag on the canvas to draw.
// Right-click this file and choose Run this file.

use core {*}
use canvas

main :: () {
    canvas.init();
    w, h := canvas.get_size();

    canvas.fill_style("#18181b");
    canvas.fill_rect(0.0f, 0.0f, w, h);

    canvas.fill_style("#9aa0a6");
    canvas.font("16px sans-serif");
    canvas.fill_text("Click and drag", 24.0f, 36.0f);

    canvas.fill_style("#7aa2f7");
    while true {
        if canvas.mouse_down() {
            x, y := canvas.mouse_position();
            canvas.begin_path();
            canvas.arc(x, y, 6.0f, 0.0f, 6.283185f);
            canvas.fill();
        }

        canvas.sync();
    }
}

// Falling particles. Right-click this file and choose Run this file.

use core {*}
use canvas

Particle :: struct {
    x, y, vx, vy, r: f32;
    color: str;
}

main :: () {
    canvas.init();
    w, h := canvas.get_size();

    colors := str.[ "#7aa2f7", "#e06c75", "#98c379", "#e5c07b", "#c678dd", "#56b6c2" ];

    particles: [40] Particle;
    for i in 0 .. 40 {
        particles[i] = .{
            random.float(0.0f, w),
            random.float(0.0f, h),
            random.float(-0.4f, 0.4f),
            random.float(0.6f, 1.8f),
            random.float(1.5f, 3.2f),
            colors[random.between(0, 5)],
        };
    }

    while true {
        canvas.fill_style("#18181b");
        canvas.fill_rect(0.0f, 0.0f, w, h);

        for i in 0 .. 40 {
            p := particles[i];
            p.x += p.vx;
            p.y += p.vy;

            if p.y > h + 8.0f {
                p.x = random.float(0.0f, w);
                p.y = -p.r;
                p.vx = random.float(-0.4f, 0.4f);
                p.vy = random.float(0.6f, 1.8f);
                p.color = colors[random.between(0, 5)];
            }

            canvas.fill_style(p.color);
            canvas.begin_path();
            canvas.arc(p.x, p.y, p.r, 0.0f, 6.283185f);
            canvas.fill();

            particles[i] = p;
        }

        canvas.sync();
    }
}

// One frame of drawing: rectangles, arcs, curves, and text.
// Right-click this file and choose Run this file.

use core {*}
use canvas

main :: () {
    canvas.init();
    w, h := canvas.get_size();

    canvas.fill_style("#18181b");
    canvas.fill_rect(0.0f, 0.0f, w, h);

    canvas.fill_style("#7aa2f7");
    canvas.font("28px sans-serif");
    canvas.text_align(canvas.TextAlign.Left);
    canvas.fill_text("Canvas", 28.0f, 48.0f);

    bars := f32.[ 0.35f, 0.62f, 0.48f, 0.80f, 0.55f ];
    bar_w := 28.0f;
    base_y := h * 0.78f;
    for i in 0 .. 5 {
        bh := bars[i] * h * 0.45f;
        canvas.fill_style("#7aa2f7");
        if i % 2 == 1 do canvas.fill_style("#56b6c2");
        canvas.fill_rect(28.0f + cast(f32) i * (bar_w + 10.0f), base_y - bh, bar_w, bh);
    }

    canvas.fill_style("#c678dd");
    canvas.begin_path();
    canvas.arc(w * 0.55f, h * 0.42f, 48.0f, 0.0f, math.TAU);
    canvas.fill();

    canvas.stroke_style("#e5c07b");
    canvas.line_width(4.0f);
    canvas.begin_path();
    canvas.ellipse(w * 0.55f, h * 0.42f, 78.0f, 36.0f, 0.4f, 0.0f, math.TAU);
    canvas.stroke();

    canvas.stroke_style("#98c379");
    canvas.line_width(3.0f);
    canvas.begin_path();
    canvas.move_to(w * 0.75f, h * 0.28f);
    canvas.line_to(w * 0.90f, h * 0.58f);
    canvas.line_to(w * 0.62f, h * 0.58f);
    canvas.close_path();
    canvas.stroke();

    canvas.stroke_style("#e06c75");
    canvas.begin_path();
    canvas.move_to(28.0f, h * 0.90f);
    canvas.quadratic_curve_to(w * 0.30f, h * 0.70f, w * 0.50f, h * 0.90f);
    canvas.bezier_curve_to(w * 0.65f, h * 1.05f, w * 0.80f, h * 0.72f, w - 28.0f, h * 0.88f);
    canvas.stroke();

    canvas.sync();
}

// Moving sine waves. Right-click this file and choose Run this file.

use core {*}
use canvas

main :: () {
    canvas.init();
    w, h := canvas.get_size();

    colors := str.[ "#7aa2f7", "#56b6c2", "#c678dd" ];
    phase := 0.0f;

    while true {
        canvas.fill_style("#18181b");
        canvas.fill_rect(0.0f, 0.0f, w, h);
        canvas.line_width(2.0f);

        for c in 0 .. 3 {
            canvas.stroke_style(colors[c]);
            canvas.begin_path();

            for i in 0 .. 64 {
                x := cast(f32) i / 63.0f * w;
                y := h * 0.5f + math.sin(x * 0.02f + phase + cast(f32) c * 0.7f) * (28.0f + cast(f32) c * 16.0f);
                if i == 0 {
                    canvas.move_to(x, y);
                } else {
                    canvas.line_to(x, y);
                }
            }

            canvas.stroke();
        }

        phase += 0.08f;
        canvas.sync();
    }
}

